import{_ as e,o as n,c as r,a2 as l,j as a}from"./chunks/framework.BkKoiSIN.js";const _=JSON.parse('{"title":"数据与监督微调实验","description":"从标签与训练目标进入真实SFT、重载、消融和独立评测。","frontmatter":{"title":"数据与监督微调实验","description":"从标签与训练目标进入真实SFT、重载、消融和独立评测。","kind":"project","status":"planned"},"headers":[],"relativePath":"projects/finetuning-lab.md","filePath":"projects/finetuning-lab.md"}'),o={name:"projects/finetuning-lab.md"};function i(d,t,s,u,p,h){return n(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="数据与监督微调实验" tabindex="-1">数据与监督微调实验 <a class="header-anchor" href="#数据与监督微调实验" aria-label="Permalink to &quot;数据与监督微调实验&quot;">​</a></h1><h2 id="问题与前置" tabindex="-1">问题与前置 <a class="header-anchor" href="#问题与前置" aria-label="Permalink to &quot;问题与前置&quot;">​</a></h2><p>选择一个有明确验证规则的小任务，研究数据质量、chat template、loss mask或LoRA配置中的一项因素。前置为<a href="/foundations/programming-math">梯度与训练机制</a>、<a href="/training/data-pretraining">数据隔离</a>和<a href="/training/sft">SFT目标</a>。</p><h2 id="实验步骤" tabindex="-1">实验步骤 <a class="header-anchor" href="#实验步骤" aria-label="Permalink to &quot;实验步骤&quot;">​</a></h2>',4),a("div",{class:"reading-table",role:"group","aria-label":"表格",tabindex:"0"},[a("table",null,[a("thead",null,[a("tr",null,[a("th",null,"步骤"),a("th",null,"必须检查"),a("th",null,"交付")])]),a("tbody",null,[a("tr",null,[a("td",null,"数据与标签"),a("td",null,"来源、近重复分组、模板、截断/packing、目标移位、padding/assistant mask"),a("td",null,"逐token标注、数据校验与train/dev/test边界")]),a("tr",null,[a("td",null,"合理基线"),a("td",null,"同一模型的可用提示设置，内容/格式/调用错误分别评分"),a("td",null,"原始输出与固定评分器")]),a("tr",null,[a("td",null,"真实SFT"),a("td",null,"冻结权重、可训练参数、rank/目标模块、学习率/有效batch、种子"),a("td",null,"参数/梯度检查、训练日志、环境与adapter")]),a("tr",null,[a("td",null,"新进程重载"),a("td",null,"base/tokenizer revision、模板、精度与adapter匹配"),a("td",null,"固定输入重载结果与差异解释")]),a("tr",null,[a("td",null,"一项消融"),a("td",null,"数据质量或mask等一项有依据的变化，其他协议可比"),a("td",null,"配对结果、错误切片、训练用量与不确定性")]),a("tr",null,[a("td",null,"能力与运行回归"),a("td",null,"任务质量之外检查长度、格式和小型保留能力"),a("td",null,"改善、无变化、退化和部署代价")])])])],-1),l('<p>LoRA是适配方法，SFT是监督信号与目标的安排；QLoRA等技术组合另检查量化基座、计算精度与可训练参数。不能把三者写成互不相关的训练目标。</p><h2 id="常见失败" tabindex="-1">常见失败 <a class="header-anchor" href="#常见失败" aria-label="Permalink to &quot;常见失败&quot;">​</a></h2><p>标签全被屏蔽、模板重复特殊token、截断删掉答案、按token ID误屏蔽有效EOS、训练/测试近重复、adapter加载错base版本，都可能造成误导结果。训练loss下降与保留任务提升分别判断。</p><p>先用极小batch验证前向、反向、保存、加载，再做有界训练。没有预算或尚未跑通时记录阻塞，不以一次toy更新替代真实SFT，也不直接宣布需要更大模型。</p><h2 id="验收" tabindex="-1">验收 <a class="header-anchor" href="#验收" aria-label="Permalink to &quot;验收&quot;">​</a></h2><p>能解释参与loss的token与可训练参数；有真实adapter和重载记录、合理基线及受控变更；能定位一次未知数据/训练故障。报告包含独立评测与退化，不提前设定必须提升的百分比。</p><p>当前全部待实践。下一步：<a href="/projects/post-training-lab">偏好优化项目</a>，或将模型部署回<a href="/projects/serving-lab">推理项目</a>做联合回归。</p>',7)])])}const b=e(o,[["render",i]]);export{_ as __pageData,b as default};
